reference_solution:
def progressive_tax_amount(brackets,income):
    previous=0;tax=0.0
    for upper,percent in brackets:
        taxed=max(0,min(income,upper)-previous);tax+=taxed*percent/100;previous=upper
        if income<=upper:break
    return tax

